        /// understand its significance in relation to specific weather conditions or
        /// activities. For example, if the index value for Outdoor Barbecue is
        /// 'Excellent', the description will be 'This is a great day for an outdoor
        /// barbecue!'
        /// </param>
        /// <returns> A new <see cref="Weather.DailyIndex"/> instance for mocking. </returns>
        public static DailyIndex DailyIndex(string indexName = default, int? indexId = default, DateTimeOffset? dateTime = default, float? value = default, string categoryDescription = default, int? categoryValue = default, bool? isAscending = default, string description = default)
